'use strict';

var uniform = require( '@stdlib/random/base/uniform' );
var bernoulli = require( '@stdlib/random/base/bernoulli' );
var incrnanapcorr = require( './../lib' );

var accumulator;
var ar;
var x;
var y;
var i;

// Initialize an accumulator:
accumulator = incrnanapcorr();

// For each simulated datum, update the sample absolute Pearson correlation coefficient...
console.log( '\nx\ty\t|r|\n' );
for ( i = 0; i < 100; i++ ) {
	x = ( bernoulli( 0.8 ) < 1 ) ? NaN : uniform( 0.0, 100.0 );
	y = ( bernoulli( 0.8 ) < 1 ) ? NaN : uniform( 0.0, 100.0 );
	ar = accumulator( x, y );
	console.log( '%d\t%d\t%d', x.toFixed( 4 ), y.toFixed( 4 ), ( ar === null ) ? NaN : ar.toFixed( 4 ) );
}
console.log( '\nFinal |r|: %d\n', accumulator() );
